install.text:
// Left 4 Dead 2 server settings, written once by Aether Panel. Your edits are kept.
// Server name, password and RCON password come from the panel (see aether.cfg),
// so do not set hostname, sv_password or rcon_password here.

// Let players join with "connect ip:port", not only through a lobby
sv_allow_lobby_connect_only 0

// LAN mode off: heartbeat, Steam authentication and public listing
sv_lan 0

// Map rotation
mapcyclefile "mapcycle.txt"

// Logging
sv_logfile 1
sv_logbans 1

// Voice
sv_voiceenable 1
sv_alltalk 1

pre.text:
// Left 4 Dead 2 server settings, written once by Aether Panel. Your edits are kept.
// Server name, password and RCON password come from the panel (see aether.cfg),
// so do not set hostname, sv_password or rcon_password here.

// Let players join with "connect ip:port", not only through a lobby
sv_allow_lobby_connect_only 0

// LAN mode off: heartbeat, Steam authentication and public listing
sv_lan 0

// Map rotation
mapcyclefile "mapcycle.txt"

// Logging
sv_logfile 1
sv_logbans 1

// Voice
sv_voiceenable 1
sv_alltalk 1

// Written by Aether Panel before every start. Changes here are overwritten:
// put your own settings in server.cfg, which is executed first.
exec server.cfg
hostname "${servername}"
sv_password "${serverpassword}"
rcon_password "${rconpassword}"
